const dialog=$('#detail-dialog');
if(dialog){document.addEventListener('click',e=>{const b=e.target.closest('[data-open]');if(!b)return;const d=content[b.dataset.open];if(!d)return;$('#detail-title').textContent=d[0];$('#detail-text').textContent=d[1];$('#detail-link').textContent=d[2];$('#detail-link').href=d[3];$('#detail-whatsapp').href=wa('Dzień dobry, mam pytanie: '+d[0]+'.');dialog.showModal()});$('.dialog-close').addEventListener('click',()=>dialog.close());dialog.addEventListener('click',e=>{if(e.target===dialog){const r=dialog.getBoundingClientRect();if(e.clientX<r.left||e.clientX>r.right||e.clientY<r.top||e.clientY>r.bottom)dialog.close()}});}
$$('[data-calc]').forEach(form=>{const input=form.querySelector('[name=amount]'),days=form.querySelector('[name=days]');function update(){const n=Number(input.value),d=Number(days.value),ok=Number.isFinite(n)&&n>=50&&n<=100000;const fee=Math.round(n*(d===15?.025:.05)*100)/100;form.querySelector('.fee').textContent=ok?money(fee):'—';form.querySelector('.total').textContent=ok?money(n+fee):'—';form.querySelector('.calc-error').hidden=ok;input.setAttribute('aria-invalid',String(!ok));const a=form.querySelector('.calc-contact');a.setAttribute('aria-disabled',String(!ok));if(ok)a.href=wa('Dzień dobry, interesuje mnie pożyczka pod zastaw: '+money(n)+' na '+d+' dni. Kalkulator wskazał opłatę '+money(fee)+'. Proszę o potwierdzenie warunków.');else a.removeAttribute('href');form.querySelectorAll('[data-amount]').forEach(b=>{const active=Number(b.dataset.amount)===n;b.classList.toggle('active',active);b.setAttribute('aria-pressed',String(active))})}form.addEventListener('submit',e=>e.preventDefault());input.addEventListener('input',update);days.addEventListener('change',update);form.querySelectorAll('[data-amount]').forEach(b=>b.addEventListener('click',()=>{input.value=b.dataset.amount;update()}));update()});
const search=$('#catalog-search');if(search){let category='all';const cards=$$('[data-category]');const normalize=s=>s.toLowerCase().normalize('NFD').replace(/[\u0300-\u036f]/g,'').replace(/ł/g,'l');function filter(){const term=normalize(search.value.trim());let count=0;cards.forEach(c=>{const show=(category==='all'||c.dataset.category===category)&&normalize(c.textContent+' '+c.dataset.keywords).includes(term);c.hidden=!show;if(show)count++});$('#result-count').textContent=count+' '+(count===1?'kategoria':count>=2&&count<=4?'kategorie':'kategorii');$('#catalog-empty').hidden=count!==0;$$('[data-filter]').forEach(b=>b.setAttribute('aria-pressed',String(b.dataset.filter===category)))}search.addEventListener('input',filter);$('#search-form').addEventListener('submit',e=>{e.preventDefault();filter();$('#oferta').scrollIntoView({behavior:'smooth'})});$$('[data-filter]').forEach(b=>b.addEventListener('click',()=>{category=b.dataset.filter;filter()}));$('#clear-filters').addEventListener('click',()=>{category='all';search.value='';filter()});filter();}
const gallery=$('[data-gallery]');if(gallery){const slides=[['jewelry-cutout.webp','Złota biżuteria','Biżuteria','Rzeczy blisko serca.','jewelry'],['coins.webp','Złote monety Krugerrand','Monety','Historia zapisana w kruszcu.','coins'],['gold-bars.webp','Złote sztabki','Sztabki','Czysta forma wartości.','bars']];let current=0;function show(i){current=(i+slides.length)%slides.length;const s=slides[current];gallery.querySelector('img').src='../../assets/'+s[0];gallery.querySelector('img').alt=s[1];$('#gallery-title').textContent=s[2];$('#gallery-caption').textContent=s[3];$('#gallery-open').dataset.open=s[4];$('#gallery-count').textContent='0'+(current+1)+' / 03';$$('[data-slide]').forEach(b=>b.setAttribute('aria-pressed',String(Number(b.dataset.slide)===current)))}$('#gallery-next').addEventListener('click',()=>show(current+1));$('#gallery-prev').addEventListener('click',()=>show(current-1));$$('[data-slide]').forEach(b=>b.addEventListener('click',()=>show(Number(b.dataset.slide))));}
const wizard=$('#service-wizard');if(wizard){let step=1,intent='';const labels={sell:'Chcę sprzedać',loan:'Potrzebuję pożyczki',buy:'Chcę coś kupić',repair:'Chcę naprawić telefon'};const recommendations={sell:['Zacznijmy od wyceny.','Przynieś przedmiot do SEZAM przy Pocztowej 11. Sprawdzimy go i przedstawimy propozycję. Ostateczną wartość ustalamy po oględzinach.'],loan:['Poznaj kwotę i koszt.','Najpierw sprawdzimy przedmiot, potem przedstawimy warunki pożyczki i termin odbioru. Możesz wcześniej skorzystać z kalkulatora poniżej.'],buy:['Obejrzyj przedmiot z bliska.','Sprawdź nasze ogłoszenia albo zapytaj o dostępność. W punkcie możesz obejrzeć wybrany przedmiot i porozmawiać o jego stanie.'],repair:['Sprawdźmy możliwości naprawy.','Podaj model telefonu i opisz usterkę. Ustalimy możliwości naprawy oraz warunki usługi.']};function render(){wizard.querySelectorAll('[data-step]').forEach(el=>el.hidden=Number(el.dataset.step)!==step);$$('[data-progress]').forEach(el=>el.classList.toggle('done',Number(el.dataset.progress)<=step));$('#step-count').textContent='KROK '+step+' Z 3';$('#wizard-back').hidden=step===1;$('#wizard-next').hidden=step===3;$('#wizard-next').disabled=step===1&&!intent;$('#wizard-reset').hidden=step!==3;if(step===2){$('#chosen-intent').textContent=labels[intent];$('#item-type').closest('label').hidden=intent==='repair';}if(step===3){const item=intent==='repair'?'Telefon':$('#item-type').value,detail=$('#item-detail').value.trim();$('#result-heading').textContent=recommendations[intent][0];$('#result-text').textContent=recommendations[intent][1];$('#result-selection').textContent=labels[intent]+' · '+item+(detail?' · '+detail:'');$('#wizard-contact').href=wa('Dzień dobry, '+labels[intent].toLowerCase()+'. Przedmiot: '+item+(detail?'. '+detail:'')+'. Proszę o informację.');$('#wizard-extra').href=intent==='loan'?'#kalkulator':intent==='buy'?'https://sezam.com.pl/oferta-olx-allegro/':'tel:+48601775146';if(intent==='buy'){$('#wizard-extra').target='_blank';$('#wizard-extra').rel='noopener'}else{$('#wizard-extra').removeAttribute('target')}$('#wizard-extra').textContent=intent==='loan'?'Oblicz koszt pożyczki':intent==='buy'?'Zobacz ogłoszenia':'Zadzwoń do SEZAM';}}wizard.addEventListener('submit',e=>{e.preventDefault();if(step===1&&!intent)return;step=Math.min(3,step+1);render()});wizard.querySelectorAll('[name=intent]').forEach(r=>r.addEventListener('change',()=>{intent=r.value;render()}));$('#wizard-back').addEventListener('click',()=>{step=Math.max(1,step-1);render()});$('#wizard-reset').addEventListener('click',()=>{step=1;intent='';wizard.reset();render()});render();}
